import os
import sys


def run(command, config_path=None, config_format=None):
    if command == 'cat-config':
        path = config_path or os.path.join(os.path.expanduser('~'), '.config', 'chezmoi', 'chezmoi.toml')
        try:
            with open(path, 'r', encoding='utf-8') as f:
                sys.stdout.write(f.read())
        except OSError as e:
            print(f'chezmoi: {e.strerror.lower() if e.strerror else "error"} {path}: {e.strerror}', file=sys.stderr)
            return 1
        return 0
    return 2
"""Filesystem listing helpers for chezmoi's unmanaged command."""
import os


def list_unmanaged(destination, paths=(), managed=(), path_style="relative",
                   nul=False, tree=False):
    """Return destination entries not present in the managed target set.

    Paths in ``managed`` and the returned relative paths are POSIX-style.
    The command lists entries at the requested directory level; it does not
    descend into directories unless a directory itself is passed as a path.
    """
    destination = os.path.abspath(os.path.expanduser(destination))
    managed = {str(p).replace(os.sep, "/").strip("/") for p in managed}
    requested = list(paths)
    output = []
    seen = set()
    roots = requested or [""]
    for arg in roots:
        p = os.path.abspath(os.path.join(destination, os.path.expanduser(arg))) if arg else destination
        try:
            common = os.path.commonpath((destination, p))
        except ValueError:
            continue
        if common != destination:
            continue
        rel = os.path.relpath(p, destination).replace(os.sep, "/")
        if rel == ".": rel = ""
        if not os.path.lexists(p):
            continue
        candidates = []
        if not requested and os.path.isdir(p) and not os.path.islink(p):
            try:
                candidates = [os.path.join(p, n) for n in os.listdir(p)]
            except OSError:
                continue
        else:
            candidates = [p]
        for candidate in candidates:
            r = os.path.relpath(candidate, destination).replace(os.sep, "/")
            if r in managed or r in seen:
                continue
            # A managed directory owns its subtree.
            if any(m and r.startswith(m + "/") for m in managed):
                continue
            seen.add(r)
            value = os.path.join(destination, r) if path_style == "absolute" else r
            output.append(value)
    output.sort()
    return ("\0" if nul else "\n").join(output) + (("\0" if nul else "\n") if output else "")
"}

