import os
import json
import dump_cmd
import fnmatch

def handle(args, source, destination):
    style='relative'; include=None; exclude=set(); paths=[]; nul=False; tree=False
    i=0
    while i<len(args):
        a=args[i]
        if a.startswith('--path-style='): style=a.split('=',1)[1]
        elif a in ('-p','--path-style') and i+1<len(args): i+=1; style=args[i]
        elif a.startswith('--include='): include=set(a.split('=',1)[1].split(','))
        elif a in ('-i','--include') and i+1<len(args): i+=1; include=set(args[i].split(','))
        elif a.startswith('--exclude='): exclude=set(a.split('=',1)[1].split(','))
        elif a in ('-x','--exclude') and i+1<len(args): i+=1; exclude=set(args[i].split(','))
        elif a in ('-0','--nul-path-separator'): nul=True
        elif a in ('-t','--tree'): tree=True
        elif a.startswith('-f') or a.startswith('--format'): pass
        elif a.startswith('-'): pass
        else: paths.append(a)
        i+=1
    ents=dump_cmd.entries(source)
    source_names={}
    ignored_patterns=[]
    try:
        with open(os.path.join(source,'.chezmoiignore'),encoding='utf-8') as f:
            ignored_patterns=[x.strip() for x in f if x.strip() and not x.lstrip().startswith('#')]
    except OSError: pass
    for root,dirs,files in os.walk(source):
        dirs[:]=sorted(d for d in dirs if d!='.git')
        for name in sorted(files):
            rel=os.path.relpath(os.path.join(root,name),source).replace(os.sep,'/')
            if rel.startswith('.chezmoi') or any(fnmatch.fnmatch(dump_cmd.source_name(rel),p) for p in ignored_patterns): continue
            target=dump_cmd.source_name(rel)
            if target.endswith('.tmpl'): target=target[:-5]
            source_names[target]=rel
    aliases={'files':'file','symlinks':'symlink','dirs':'dir'}
    if include is not None: include={aliases.get(x,x) for x in include}
    exclude={aliases.get(x,x) for x in exclude}
    names=[]
    for n,v in ents.items():
        if include is not None and v.get('type') not in include: continue
        if v.get('type') in exclude: continue
        if paths and not any(n==p or n.startswith(p.rstrip('/')+'/') for p in paths): continue
        if style in ('absolute','relative'):
            val=os.path.join(os.path.abspath(os.path.expanduser(destination)),n) if style=='absolute' else n
        elif style in ('source-absolute','source-relative'):
            src=source_names.get(n,n)
            val=os.path.join(os.path.abspath(source),src) if style=='source-absolute' else src
        elif style=='all': val=n
        else: val=n
        names.append(val)
    sep='\0' if nul else '\n'
    return sep.join(names)+(sep if names else '')

def ignored(source, nul=False):
    pats=[]
    try:
        with open(os.path.join(source,'.chezmoiignore'),encoding='utf-8') as f:
            pats=[x.strip() for x in f if x.strip() and not x.lstrip().startswith('#')]
    except OSError: return ''
    names=[]
    for root,dirs,files in os.walk(source):
        dirs[:]=sorted(dirs)
        for name in sorted(files+dirs):
            rel=os.path.relpath(os.path.join(root,name),source).replace(os.sep,'/')
            target=dump_cmd.source_name(rel)
            if any(fnmatch.fnmatch(target,p) for p in pats): names.append(target)
    names=sorted(set(names)); sep='\0' if nul else '\n'
    return sep.join(names)+(sep if names else '')
"}

