def entries(source, include_empty=False):
    SCRIPT_PHASES.clear()
    result = {}
    if not os.path.isdir(source):
        return result
    ignore=[]
    try:
        ignore=[x.strip() for x in open(os.path.join(source,'.chezmoiignore'),encoding='utf-8') if x.strip() and not x.lstrip().startswith('#')]
    except OSError: pass
    try: data=json.load(open(os.path.join(source,'.chezmoidata.json'),encoding='utf-8'))
    except Exception: data={}
    for root, dirs, files in os.walk(source):
        dirs[:] = sorted(d for d in dirs if d != '.git')
        for name in sorted(files + dirs):
            p = os.path.join(root, name)
            rel = os.path.relpath(p, source)
            if rel.startswith('.chezmoi') or name in ('.git','.keep') or any(path_match(source_name(rel), pat) for pat in ignore):
                continue
            target = source_name(rel)
            st = os.lstat(p)
            if stat.S_ISLNK(st.st_mode):
                result[target] = {'type': 'symlink', 'name': target, 'linkname': os.readlink(p)}
            elif stat.S_ISDIR(st.st_mode):
                perm=stat.S_IMODE(st.st_mode)
                base=os.path.basename(rel)
                attrs=source_attributes(base)
                if 'private' in attrs: perm &= 0o700
                if 'readonly' in attrs: perm &= 0o555
                result[target]={'type':'dir','name':target,'perm':perm}
